# DK KEV.  Kolding - Egtved
#
let kk = path("d3.dk.kev.1");
let ke = path("d3.dk.kev.2");

with detail = 4, railway = :third :narrow:g1000 :pax :removed {
    # point.dk.Kolding  dk.FPB

    with link = "line.dk.KEV" {
        track(:station,
                kk[:kol.yt - 0.1dl, :kol.yt] << 1.5mo
            ..  kk[:kol.xt, :kol.xt + 0.1dl]
        );
        track(kk[:kol.xt, :kol.xt + 0.21km]);
        line_label(:left:n, kk[:kol.xt + 0.2km] << 0.5lt, "KEV");
        track(kk[:kol.xt + 0.19km, :kon.ye - 0.9seg]);
        track(:station, kk[:kon.ye - 1seg, :kon.ye + 0.1dl]);
    }

    with link = "point.dk.Kolding-Nord", railway = :station {
        track(kk[:kon.ye, :kon.f]);
        marker(:left :de.bf, kk[:kon] << 0.5lt);
        station(:bottom, kk[:kon] << 0.5lt << 1sh << 0.8dt,
            "Kolding Nord", "KEV: 2,2"
        );
    }

    with link = "line.dk.KEV" {
        track(:station, ke[:kon.ye, :kon.ye + 1seg]);
        track(:ror, ke[:kon.ye + 0.9seg, :kon.ze]);
        track(ke[:kon.ze - 0.1dl, :kon.ze + 0.68km]);
